const project = $input.first().json.rows[0];
const text = project.text_content;

// Split chapters using regex patterns for common novel formats
const chapterPatterns = [
  /(?:^|\n)\s*(?:CHAPTER|Chapter)\s+(\d+|[IVXLCDM]+)[.:\s]*(.*?)(?=\n|$)/gm,
  /(?:^|\n)\s*(?:Ch\s*\.?\s*\d+)[.:\s]*(.*?)(?=\n|$)/gm,
  /(?:^|\n)\s*(?:Part\s+\d+)[.:\s]*(.*?)(?=\n|$)/gm,
];

let chapters = [];
let usedPattern = null;

for (const pattern of chapterPatterns) {
  const matches = [...text.matchAll(pattern)];
  if (matches.length > 2) {
    usedPattern = pattern;
    chapters = matches.map((match, index) => {
      const startIdx = text.indexOf(match[0]);
      return {
        number: index + 1,
        title: match[2] ? match[2].trim() : `Chapter ${match[1]}`,
        content: '',
        start_index: startIdx
      };
    });
    break;
  }
}

// If no pattern matched, split by double newlines as paragraphs
if (chapters.length === 0) {
  const paragraphs = text.split(/\n\n+/);
  const chunkSize = Math.ceil(paragraphs.length / Math.max(1, Math.ceil(text.split(/\s+/).length / 5000)));
  for (let i = 0; i < paragraphs.length; i += chunkSize) {
    const chunk = paragraphs.slice(i, i + chunkSize);
    chapters.push({
      number: chapters.length + 1,
      title: `Part ${chapters.length + 1}`,
      content: '',
      start_index: text.indexOf(chunk[0])
    });
  }
}

// Extract actual content for each chapter
for (let i = 0; i < chapters.length; i++) {
  const start = chapters[i].start_index;
  const end = i + 1 < chapters.length ? chapters[i + 1].start_index : text.length;
  chapters[i].content = text.substring(start, end).trim();
  delete chapters[i].start_index;
}

return [{
  json: {
    project_id: project.project_id,
    title: project.title,
    author: project.author,
    language: project.language,
    total_chapters: chapters.length,
    chapters: chapters
  }
}];

