const llmResponse = JSON.parse($input.first().json.response || $input.first().json.text || '{}');
let scenes = [];

try {
  // Try to extract JSON from the response
  const responseText = llmResponse.response || '';
  const jsonMatch = responseText.match(/\[[\s\S]*\]/);
  if (jsonMatch) {
    scenes = JSON.parse(jsonMatch[0]);
  }
} catch (e) {
  scenes = [{
    scene_number: 1,
    title: 'Opening Scene',
    summary: 'Auto-generated fallback scene',
    characters_present: [],
    location: 'Unknown',
    time_period: 'Unknown',
    emotional_tone: 'neutral',
    word_count: 0
  }];
}

const projectId = $('Execute Logic').item.json.project_id;
const chapterData = $('Execute Logic').item.json.chapters;

// Map scenes back to chapters and store
const chapterId = $('Store Chapters').item.json.chapter_id;

const sceneInserts = scenes.map((scene, idx) => ({
  json: {
    project_id: projectId,
    chapter_id: chapterId,
    scene_number: scene.scene_number || idx + 1,
    title: scene.title || `Scene ${idx + 1}`,
    summary: scene.summary || '',
    characters_present: JSON.stringify(scene.characters_present || []),
    location: scene.location || 'Unknown',
    time_period: scene.time_period || 'Unknown',
    emotional_tone: scene.emotional_tone || 'neutral',
    word_count: scene.word_count || 0
  }
}));

return sceneInserts.length > 0 ? sceneInserts : [{ json: { no_scenes: true } }];

